P = [
 dict(pmid='43067074', doi='10.1016/j.ecoenv.2026.121090', journal='Ecotoxicol Environ Saf', title='Prenatal ambient PM(2.5) exposure during pregnancy and postpartum depression: A prospective Birth Cohort study in China.', tier='A', basis='Model (CTM / LUR / ML)', short='China Southwest Birth Cohort, n=10,568: whole-pregnancy PM2.5 OR 1.28 (1.06-1.54) per 10 ug/m3 for postpartum depression; 1.79 among tobacco-exposed; 9.7% mediated by antenatal symptoms', design='Prospective cohort', pm='Residential PM2.5 estimated for whole pregnancy and each trimester (estimation method not stated in abstract); two-stage residual inclusion with wind speed as instrument', geo='China (Southwest, multicentre)', endpoint='Postpartum depression (EPDS at 6 weeks)', n='Multicentre China Southwest Birth Cohort, 10,568 women; PPD by EPDS at 6 weeks postpartum (22.1% prevalent), antenatal symptoms by EPDS in the second trimester. Each 10 ug/m3 of whole-pregnancy PM2.5 was associated with OR 1.28 (95% CI 1.06-1.54) for PPD after a two-stage residual-inclusion IV correction using wind speed; OR 1.79 (1.25-2.57) among tobacco-smoke-exposed women (P-heterogeneity 0.046); second trimester OR 1.18 (1.02-1.38), increment not restated. Antenatal symptoms mediated 9.7% of the second-trimester effect. Weakness: wind speed is a weak and probably invalid instrument - it moves heat, humidity and other pollutants that plausibly affect mood - and the exposure model is not described. Relevance: modest, but a large cohort where personal or home sensors would test whether the IV correction removes or adds bias.', sub=corpus.NEU),
 dict(pmid='43068907', doi='10.1111/ppe.70211', journal='Paediatr Perinat Epidemiol', title='Ambient Air Pollution, Weather and Placental Abruption (APWA): Design, Data Linkage and Preliminary Findings.', tier='B', basis='Model (CTM / LUR / ML)', short='APWA: 13.6 million linked deliveries in four US states (2000-2016), 144,930 abruptions; daily modelled PM2.5, NO2, O3 and weather from 90 days pre-LMP to 12 months postpartum', design='Retrospective cohort', pm='Daily modelled PM2.5, NO2 and O3 plus temperature, humidity and dew point at geocoded residence at delivery, from 90 days before LMP to 12 months after delivery', geo='USA (California, Florida, Massachusetts, South Carolina)', endpoint='Placental abruption (chronic vs acute), cohort design and linkage', n='Cohort-profile paper. Vital records for live births and fetal deaths in California, Florida, Massachusetts and South Carolina (2000-2016) linked to delivery hospitalisations: 13,612,485 of 14,756,201 births (94%) linked to abruption diagnosis and to daily modelled pollutant and weather exposures. Abruption prevalence 1.0-1.4% by state (86,803 in California). Exposure distributions were similar for abruption and non-abruption births, with heterogeneity by state and season. No effect estimate yet. Weakness: residence at delivery only, so pre-conception and early-pregnancy windows - the paper\'s own chronic-abruption hypothesis - carry the largest misclassification; exposure model not named in the abstract. Relevance: the acute vs chronic window contrast will hinge on daily exposure accuracy, which is where dense networks add most over gridded models.', sub=corpus.REPR),
 dict(pmid='43068586', doi='10.1016/j.ecoenv.2026.120993', journal='Ecotoxicol Environ Saf', title='Different diameters of particulate matter exposure and health outcomes: An umbrella review.', tier='B', basis='Review / no primary exposure', short='Umbrella review of PM1/PM2.5/PM10 meta-analyses with GRADE: PM1 RR 1.30 metabolic syndrome, 1.41 childhood obesity, 1.61 childhood hypertension, 1.59 NAFLD - higher than PM2.5/PM10', design='Umbrella review / meta-analysis', pm='PM1, PM2.5 and PM10 as reported in the pooled meta-analyses (harmonised effect estimates)', geo='Global / multi-region', endpoint='Multiple outcomes: metabolic syndrome, childhood obesity and hypertension, NAFLD, autism, asthma', n='Umbrella review of observational meta-analyses, harmonising effect estimates by particle size and grading certainty with GRADE. PM1 carried the largest pooled relative risks: metabolic syndrome RR 1.30, childhood obesity 1.41, childhood hypertension 1.61 and NAFLD 1.59 (moderate certainty); similar size gradients were reported for autism and asthma. CIs, increments and the number of included meta-analyses are not given in the abstract, so these are not plotted. Weakness: PM1 meta-analyses draw on few, mostly Chinese cohorts with modelled PM1 highly collinear with PM2.5, and RRs per unspecified increments cannot be compared across fractions - the "size effect" may be an artefact of increment scaling. Relevance: direct - many optical low-cost sensors report PM1, but its health signal is only as good as its separation from PM2.5.', sub=corpus.CVM),
 dict(pmid='43068838', doi='10.5620/eaht.2026012', journal='Environ Anal Health Toxicol', title='Indoor air pollution and health outcomes in women in developing Asian countries: a systematic review.', tier='C', basis='Review / no primary exposure', short='Systematic review, 28 studies: household solid-fuel smoke in Asian women linked to respiratory symptoms (aOR 3.0), birth defects (aOR up to 7.09), stillbirth (aOR 1.34)', design='Systematic review', pm='Household air pollution from solid-fuel combustion; mostly fuel type as proxy, measurement not characterised in abstract', geo='Asia (developing countries, multi-country)', endpoint='Respiratory symptoms, lung function, birth defects, stillbirth, cardiometabolic disease, genotoxicity, cognition', n='PRISMA review of five databases, 28 studies of women in developing Asian countries, quality appraised with NOS, AXIS and OHAT. Household air pollution, mainly solid-fuel combustion, was associated with respiratory symptoms (aOR 3.0), reduced lung function, birth defects (aOR up to 7.09), stillbirth (aOR 1.34), cardiometabolic risk, genotoxicity and cognitive decline. No pooling and no CIs in the abstract. Weakness: exposure is overwhelmingly fuel type rather than measured PM, the selected maxima (7.09) are cherry-picked single studies, and confounding by poverty is the obvious alternative. Relevance: household-energy studies are where cheap personal PM monitors would replace the fuel-type proxy.', sub=corpus.OCC),
]
